// src/api/api.js
// URL de base — ton backend tourne sur le port 8081
const BASE_URL = "http://localhost:8081/api";

// Helper générique
async function request(method, path, body = null) {
  const options = {
    method,
    headers: { "Content-Type": "application/json" },
  };
  if (body) options.body = JSON.stringify(body);

  const res = await fetch(`${BASE_URL}${path}`, options);
  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err.erreur || `Erreur ${res.status}`);
  }
  // 204 No Content
  if (res.status === 204) return null;
  return res.json();
}

// ── Affectations (Phase 1) ──────────────────────────────
export const affectationApi = {
  getAll:        ()               => request("GET",  "/affectations"),
  getEnAttente:  ()               => request("GET",  "/affectations/en-attente"),
  getValidees:   ()               => request("GET",  "/affectations/validees"),
  getRefusees:   ()               => request("GET",  "/affectations/refusees"),
  valider:       (id)             => request("PUT",  `/affectations/${id}/valider`),
  refuser:       (id, commentaire)=> request("PUT",  `/affectations/${id}/refuser`, { commentaire }),
  modifier:      (id, sujetId, commentaire) =>
                                     request("PUT",  `/affectations/${id}/modifier`, { sujetId, commentaire }),
  validerToutes: ()               => request("PUT",  "/affectations/valider-toutes"),
};

// ── Créneaux (Phase 2) ─────────────────────────────────
export const creneauApi = {
  getDisponibles: ()        => request("GET",  "/creneaux"),
  creer:          (creneau) => request("POST", "/creneaux", creneau),
};

// ── Disponibilités (Phase 2) ───────────────────────────
export const disponibiliteApi = {
  getParProf:    (profId) => request("GET",  `/disponibilites/${profId}`),
  enregistrer:   (dispo)  => request("POST", "/disponibilites", dispo),
};

// ── Soutenances (Phase 3 & 4) ──────────────────────────
export const soutenanceApi = {
  getPlanningFinal:    ()           => request("GET",  "/soutenances"),
  getPlanningParDate:  (date)       => request("GET",  `/soutenances?date=${date}`),
  planifier:           (data)       => request("POST", "/soutenances/planifier", data),
  planifierAuto:       ()           => request("POST", "/soutenances/planifier-auto"),
  enregistrerResultat: (id, data)   => request("PUT",  `/soutenances/${id}/resultat`, data),
};

// ── Choix sujets ───────────────────────────────────────
export const choixApi = {
  getParBinome:  (binomeId)              => request("GET",    `/choix/binome/${binomeId}`),
  ajouter:       (binomeId, sujetId, ordre) =>
                                            request("POST",   "/choix", { binomeId, sujetId, ordre }),
  supprimer:     (id)                    => request("DELETE", `/choix/${id}`),
  reinitialiser: (binomeId)              => request("DELETE", `/choix/binome/${binomeId}/reset`),
};
